CREATE OR REPLACE FUNCTION public.guard_demo_marker() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.is_demo IS DISTINCT FROM OLD.is_demo AND coalesce(current_setting('app.loading_demo',true),'')<>'on' THEN RAISE EXCEPTION 'Demo markers can only be set by the demo loader'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_demo_marker BEFORE UPDATE ON public.clubs FOR EACH ROW EXECUTE FUNCTION public.guard_demo_marker();
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.load_demo(boolean)'::regprocedure) INTO definition; definition:=replace(definition,'UPDATE public.clubs SET name=', 'PERFORM set_config(''app.loading_demo'',''on'',true); UPDATE public.clubs SET name='); definition:=replace(definition,'RETURN cid;', 'PERFORM set_config(''app.loading_demo'','''',true); RETURN cid;'); EXECUTE definition; END $$;